draw(unitsquare);
draw((0,0)--(1,0),EndArrow);
draw((0,0)--(0,1),EndArrow);
label("0",(0,0),SW);
label("1",(1,0),S);
label("1",(0,1),W);
label("$x$",(.5,0),S);
